js部分代码



```javascript
window.onload = carouselInit(600, 6, '#carousel', 2000);
  /**
  * 轮播图初始化函数
  * @params {imgWidth} 单张图片宽度数值
  * @params {num} 轮播图中图片总数量
  * @params {id} 轮播图盒子id
  * @params {time} 自动轮播时间间隔
  */
  function carouselInit(imgWidth, num, id, time) {
    if (!imgWidth || !num || !id || !time === true) {
      console.info('参数缺失！！！')
      return false;
    };
    var container = document.querySelector(id)
    var wrapper = container.querySelector('.wrapper');
    var prevNode = container.querySelector('.prev')
    var nextNode = container.querySelector('.next')
    var dots = container.querySelectorAll('.button span')
    var flag = true; // 防止重复点击标识
    var index = 0;
    // 设置ul总宽度
    wrapper.style.width = imgWidth * 6 + 'px';
    /**
    * 滑动到上一张执行函数
    */
    function prev() {
      index--;
      index < 0 ? index = num - 1 : true;
      if (flag) {
        if (window.getComputedStyle(wrapper).left === '0px') {
          wrapper.style.left = -imgWidth * (num - 1) + 'px';
        } else {
          var prevPosition = parseFloat(window.getComputedStyle(wrapper).left) + imgWidth;
          wrapper.style.left = prevPosition + 'px';
        }
        setTimeout(function() {
          flag = true;
          currentDot();
        }, 1000);
      };
    }

    /**
    * 滑到下一张执行函数
    */
    function next() {
      index++;
      index > (num - 1) ? index = 0 : true;
      if (flag) {
        flag = false;
        if (window.getComputedStyle(wrapper).left === -imgWidth * (num - 1) + 'px') {
          wrapper.style.left = '0px';
        } else {
          var nextPosition = parseFloat(window.getComputedStyle(wrapper).left) - imgWidth;
          wrapper.style.left = nextPosition + 'px';
        }
        setTimeout(function() {
          flag = true;
          currentDot();
        }, 1000);
      };
    }

    nextNode.addEventListener('click', function() {
        next();
    });
    prevNode.addEventListener('click', function() {
        prev();
    });

    /**
    * 小圆点变化执行函数
    */
    function currentDot() {
      for (var i = 0; i < dots.length; i++) {
        dots[i].classList.remove('on')
      }
      dots[index].classList.add('on')
    }

    /**
    * 点击小圆点滑动到对应图片
    */
    for (var i = 0; i < dots.length; i++) {
      (function(i) {
        dots[i].addEventListener('click', function() {
          index = i;
          wrapper.style.left = -imgWidth * i + 'px';
          currentDot();
        });
      })(i);
    };

    /**
    * 自动轮播
    */
    var autoPlay = setInterval(function() {
      next()
    }, time);

    /**
    * 鼠标移入轮播图盒子停止轮播
    * 鼠标移出轮播图盒子开始轮播
    */
    container.addEventListener('mouseover', function() {
      clearInterval(autoPlay);
    });
    container.addEventListener('mouseout', function() {
      autoPlay = setInterval(function() {
        next()
      }, time);
    })
  }
```

